export interface PaginationOptions {
  limit?: number;
  offset?: number;
}

export interface PaginatedResult<T> {
  items: T[];
  total: number;
  hasMore: boolean;
}

export async function searchTodos(
  keyword: string,
  options: PaginationOptions = {}
): Promise<PaginatedResult<Todo>> {
  const limit = Math.min(options.limit || 50, 100);
  const offset = options.offset || 0;
  const searchPattern = `%${keyword}%`;

  const countQuery = 'SELECT COUNT(*) as total FROM todos WHERE title LIKE $1 OR description LIKE $1';
  const countResult = await db.query(countQuery, [searchPattern]);
  const total = parseInt(countResult[0].total, 10);

  const query = 'SELECT * FROM todos WHERE title LIKE $1 OR description LIKE $1 ORDER BY created_at DESC LIMIT $2 OFFSET $3';
  const rows = await db.query(query, [searchPattern, limit, offset]);

  return {
    items: rows as Todo[],
    total,
    hasMore: offset + limit < total
  };
}

